/////////////////\n  // RACK\n  /////////////////////////////////////////////////////////\n\n  rackId String?\n\n  rack Rack? @relation(\"RackAtivos\", fields: [rackId], references: [id], onDelete: SetNull)\n\n  posicaoRack Int?\n\n  tamanhoU Int?\n\n  /////////////////////////////////////////////////////////\n  // APLICAÇÕES\n  /////////////////////////////////////////////////////////\n\n  aplicacoes Aplicacao[] @relation(\"AppServidores\")\n\n  /////////////////////////////////////////////////////////\n  // GLPI\n  /////////////////////////////////////////////////////////\n\n  glpiId Int?\n\n  glpiLastSync DateTime?\n\n  /////////////////////////////////////////////////////////\n  // TIMESTAMPS\n  /////////////////////////////////////////////////////////\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  /////////////////////////////////////////////////////////\n  // INDEXES\n  /////////////////////////////////////////////////////////\n\n  @@index([hostname])\n  @@index([serial])\n  @@index([tipo])\n  @@index([status])\n  @@index([powerState])\n  @@index([rackId])\n  @@index([hostFisicoId])\n  @@index([userId])\n  @@index([glpiId])\n}\n\n///////////////////////////////////////////////////////////\n// REDE\n///////////////////////////////////////////////////////////\n\nmodel ConfigRede {\n  id Int @id @default(autoincrement())\n\n  ipAddress String?\n\n  macAddress String? @unique\n\n  gateway String?\n\n  mascara String?\n\n  dns String?\n\n  vlan Int?\n\n  interface String?\n\n  velocidade String?\n\n  portasUTP Int?\n\n  portasFibra Int?\n\n  storageConectado String?\n\n  discoStorage String?\n\n  ativoId Int\n\n  ativo Ativo @relation(fields: [ativoId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([ipAddress])\n  @@index([ativoId])\n}\n\n///////////////////////////////////////////////////////////\n// APLICAÇÕES\n///////////////////////////////////////////////////////////\n\nmodel Aplicacao {\n  id Int @id @default(autoincrement())\n\n  nome String\n\n  sigla String? @unique\n\n  descricao String? @db.Text\n\n  categoria SistemaCategoria @default(OPERACIONAL)\n\n  criticidade Criticidade @default(MEDIA)\n\n  businessOwner String?\n\n  responsavelTecnico String?\n\n  contatoFuncional String?\n\n  fornecedor String?\n\n  url String?\n\n  repositorio String?\n\n  documentacao String?\n\n  janelaOperacao String?\n\n  backupInfo String?\n\n  procedimentoRecup String? @db.Text\n\n  pontoUnicoFalha String? @db.Text\n\n  tecnologiaPrincipal String?\n\n  databaseInfo String?\n\n  integracoes String? @db.Text\n\n  servidores Ativo[] @relation(\"AppServidores\")\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  @@index([nome])\n  @@index([categoria])\n}\n\n///////////////////////////////////////////////////////////\n// ENUMS\n///////////////////////////////////////////////////////////\n\nenum Role {\n  USER\n  USER_INFRA\n  USER_DEV\n  ADMIN\n  SUPER_ADMIN\n  ADMIN_INFRA\n  ADMIN_DEV\n  ADMIN_DEVOPS\n  MANAGER_INFRA\n  MANAGER_DEV\n  MANAGER_DEVOPS\n}\n\nenum AtivoTipo {\n  LAPTOP\n  DESKTOP\n  SERVIDOR_FISICO\n  SERVIDOR_VIRTUAL\n  SWITCH\n  ROTEADOR\n  STORAGE\n  FIREWALL\n  ACCESS_POINT\n  IMPRESSORA\n  MONITOR\n  NOBREAK\n}\n\nenum AtivoStatus {\n  DISPONIVEL\n  EM_USO\n  MANUTENCAO\n  DESCARTADO\n}\n\nenum PowerState {\n  ON\n  OFF\n  SUSPENDED\n  PAUSED\n}\n\nenum SistemaCategoria {\n  ADMINISTRATIVO\n  OPERACIONAL\n  MONITORAMENTO\n  DEVOPS\n  SEGURANCA\n}\n\nenum Criticidade {\n  BAIXA\n  MEDIA\n  ALTA\n  CRITICA\n}\n\nenum HypervisorTipo {\n  VMWARE\n  HYPERV\n  PROXMOX\n  KVM\n  XEN\n}\n\nenum AuthProvider {\n  LOCAL\n  AD\n}\n",
